use serde::{Deserialize, Serialize};
use std::collections::HashMap;

# [doc = " Optional pre-release identifier on a version string. This comes after `-` in"] # [doc = " a SemVer version, like `1.0.0-alpha.1`"] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " Some real world pre-release idioms drawn from crates.io:"] # [doc = ""] # [doc = " - **[mio]** <code>0.7.0-<b>alpha.1</b></code> &mdash; the most common style"] # [doc = "   for numbering pre-releases."] # [doc = ""] # [doc = " - **[pest]** <code>1.0.0-<b>beta.8</b></code>,&ensp;<code>1.0.0-<b>rc.0</b></code>"] # [doc = "   &mdash; this crate makes a distinction between betas and release"] # [doc = "   candidates."] # [doc = ""] # [doc = " - **[sassers]** <code>0.11.0-<b>shitshow</b></code> &mdash; ???."] # [doc = ""] # [doc = " - **[atomic-utils]** <code>0.0.0-<b>reserved</b></code> &mdash; a squatted"] # [doc = "   crate name."] # [doc = ""] # [doc = " [mio]: https://crates.io/crates/mio"] # [doc = " [pest]: https://crates.io/crates/pest"] # [doc = " [atomic-utils]: https://crates.io/crates/atomic-utils"] # [doc = " [sassers]: https://crates.io/crates/sassers"] # [doc = ""] # [doc = " *Tip:* Be aware that if you are planning to number your own pre-releases,"] # [doc = " you should prefer to separate the numeric part from any non-numeric"] # [doc = " identifiers by using a dot in between. That is, prefer pre-releases"] # [doc = " `alpha.1`, `alpha.2`, etc rather than `alpha1`, `alpha2` etc. The SemVer"] # [doc = " spec's rule for pre-release precedence has special treatment of numeric"] # [doc = " components in the pre-release string, but only if there are no non-digit"] # [doc = " characters in the same dot-separated component. So you'd have `alpha.2` &lt;"] # [doc = " `alpha.11` as intended, but `alpha11` &lt; `alpha2`."] # [doc = ""] # [doc = " # Syntax"] # [doc = ""] # [doc = " Pre-release strings are a series of dot separated identifiers immediately"] # [doc = " following the patch version. Identifiers must comprise only ASCII"] # [doc = " alphanumerics and hyphens: `0-9`, `A-Z`, `a-z`, `-`. Identifiers must not be"] # [doc = " empty. Numeric identifiers must not include leading zeros."] # [doc = ""] # [doc = " # Total ordering"] # [doc = ""] # [doc = " Pre-releases have a total order defined by the SemVer spec. It uses"] # [doc = " lexicographic ordering of dot-separated components. Identifiers consisting"] # [doc = " of only digits are compared numerically. Otherwise, identifiers are compared"] # [doc = " in ASCII sort order. Any numeric identifier is always less than any"] # [doc = " non-numeric identifier."] # [doc = ""] # [doc = " Example:&ensp;`alpha`&ensp;&lt;&ensp;`alpha.85`&ensp;&lt;&ensp;`alpha.90`&ensp;&lt;&ensp;`alpha.200`&ensp;&lt;&ensp;`alpha.0a`&ensp;&lt;&ensp;`alpha.1a0`&ensp;&lt;&ensp;`alpha.a`&ensp;&lt;&ensp;`beta`"] # [derive (Default , Clone , Eq , PartialEq , Hash)] pub struct Prerelease { identifier : Identifier , }